def _scrub(value: Any) -> Any:
    if isinstance(value, dict):
        return {
            k: (_REDACTED if k.lower().replace("-", "").replace("_", "") in _SENSITIVE_KEYS else _scrub(v))
            for k, v in value.items()
        }
    if isinstance(value, list):
        return [_scrub(v) for v in value]
    return value

